package com.ruoyi.paismart.api;
import com.ruoyi.common.annotation.Anonymous;
import com.ruoyi.common.annotation.Log;
import com.ruoyi.common.enums.BusinessType;
import com.ruoyi.common.core.controller.BaseController;
import com.ruoyi.common.core.domain.AjaxResult;
import com.ruoyi.common.core.page.TableDataInfo;
import com.ruoyi.paismart.application.PaismartIdentity;
import com.ruoyi.paismart.application.spaces.SpaceService;
import com.ruoyi.paismart.application.jobs.JobService;
import com.ruoyi.paismart.application.intelligence.*;
import com.ruoyi.paismart.configuration.PaismartEnabled;
import com.ruoyi.paismart.infrastructure.intelligence.Values;
import org.springframework.web.bind.annotation.*;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.http.HttpStatus;
import jakarta.servlet.http.HttpServletRequest;
import java.util.*;

@RestController
@PaismartEnabled
@RequestMapping("/paismart")
public class IntelligenceController extends BaseController {
    private final SearchService search;private final ChatService chat;private final CitationService references;private final ProviderService providers;private final GovernanceService governance;private final WebSocketTicketService tickets;
    private final OcrService ocr;
    private final ModelCallService calls;
    public IntelligenceController(SearchService search,ChatService chat,CitationService references,ProviderService providers,GovernanceService governance,WebSocketTicketService tickets,OcrService ocr,ModelCallService calls){this.search=search;this.chat=chat;this.references=references;this.providers=providers;this.governance=governance;this.tickets=tickets;this.ocr=ocr;this.calls=calls;}
    private SpaceService.Scope scope(){var a=PaismartIdentity.current();return new SpaceService.Scope(a.userId(),a.administrator());}
    private TableDataInfo page(List<?> rows,int page,int size){page=Math.max(1,page);size=Values.range(size,20,1,100);int start=Math.min(rows.size(),(page-1)*size);return PaismartTables.page(rows.subList(start,Math.min(rows.size(),start+size)),rows.size());}
    private String dateFilter(Map<String,String> filters,String canonical,String legacy){return filters.getOrDefault(canonical,filters.get(legacy));}
    private Map<String,Object> job(JobService.Job j){return Map.of("id",j.id(),"jobId",j.id(),"state",j.state(),"kind",j.type(),"rowVersion",j.rowVersion(),"result",j.result());}
    @GetMapping("/search/hybrid") @PreAuthorize("@ss.hasPermi('paismart:search:query')")
    public AjaxResult search(@RequestParam String query,@RequestParam(defaultValue="5")int topK,@RequestParam(required=false)String spaceId){var result=search.search(scope(),query,topK,spaceId);Map<String,Object> out=new LinkedHashMap<>();out.put("hits",result.rows());out.put("scoreType",result.scoreType());out.put("degraded",!result.degradation().isEmpty());out.put("reason",String.join("；",result.degradation()));out.put("indexRevision",search.activeIndex().get("id"));return success(out);}
    @PostMapping("/chat/ws-ticket") @PreAuthorize("@ss.hasPermi('paismart:chat:send')")
    public AjaxResult ticket(@RequestBody(required=false)Map<String,Object> body,HttpServletRequest request){String origin=request.getHeader("Origin");if(origin==null&&body!=null)origin=Values.text(body.get("origin"));return success(tickets.issue(origin));}
    @Anonymous @GetMapping(value="/ws/chat",headers="!Upgrade") @ResponseStatus(HttpStatus.UPGRADE_REQUIRED)
    public void upgradeRequired() { }
    @Anonymous @PostMapping("/internal/ocr/liteparse") public Map<String,Object> ocr(@RequestParam String token,@RequestParam org.springframework.web.multipart.MultipartFile file)throws java.io.IOException {if(file.getSize()>10*1024*1024)throw new IllegalArgumentException("OCR图片超出预算");return ocr.recognize(token,file.getBytes());}
    @GetMapping("/operations/ocr-health") @PreAuthorize("@ss.hasPermi('paismart:operation:plan')") public AjaxResult ocrHealth(){return success(ocr.health());}
    @PostMapping("/operations/ocr-health") @PreAuthorize("@ss.hasPermi('paismart:provider:test')") @Log(title="知识OCR真实健康调用",businessType=BusinessType.OTHER,isSaveRequestData=false,isSaveResponseData=false) public AjaxResult ocrHealthTest(@RequestHeader("Idempotency-Key")String key,@RequestParam org.springframework.web.multipart.MultipartFile file)throws java.io.IOException{if(!PaismartIdentity.current().administrator())throw new IllegalArgumentException("OCR健康真调用仅允许平台管理员");if(file.getSize()>10*1024*1024)throw new IllegalArgumentException("OCR图片超出预算");return success(ocr.healthRecognize(PaismartIdentity.userId(),key,file.getBytes()));}
    @GetMapping("/operations/ocr-calls") @PreAuthorize("@ss.hasPermi('paismart:operation:plan')") public TableDataInfo ocrCalls(){var actor=PaismartIdentity.current();var rows=ocr.unresolved().stream().filter(row->actor.administrator()||actor.userId()==Values.number(row.get("userId"),0)).toList();return PaismartTables.page(rows,rows.size());}
    @PostMapping("/operations/ocr-calls/{id}/reconcile") @PreAuthorize("@ss.hasPermi('paismart:operation:execute')") @Log(title="知识OCR计费页核对",businessType=BusinessType.UPDATE) public AjaxResult reconcileOcr(@PathVariable String id,@RequestBody Map<String,Object> body){if(!PaismartIdentity.current().administrator())throw new IllegalArgumentException("OCR调用用量核对仅允许平台管理员");ocr.reconcile(id,Values.range(body.get("actualPages"),-1,0,1),Values.required(body,"reason",500));return success();}
    @GetMapping("/operations/model-calls") @PreAuthorize("@ss.hasPermi('paismart:operation:plan')") public TableDataInfo modelCalls(){var actor=PaismartIdentity.current();var rows=calls.unresolved(actor.userId(),actor.administrator());return PaismartTables.page(rows,rows.size());}
    @PostMapping("/operations/model-calls/{id}/reconcile") @PreAuthorize("@ss.hasPermi('paismart:operation:execute')") @Log(title="知识模型用量核对",businessType=BusinessType.UPDATE) public AjaxResult reconcile(@PathVariable String id,@RequestBody Map<String,Object> body){if(!PaismartIdentity.current().administrator())throw new IllegalArgumentException("调用用量核对仅允许平台管理员");return success(calls.reconcile(id,Values.number(body.get("actualTokens"),-1),Values.required(body,"reason",500)));}
    @GetMapping("/audit/conversations") @PreAuthorize("@ss.hasPermi('paismart:conversation:audit')") public TableDataInfo audit(@RequestParam(required=false)Long userId,@RequestParam(required=false)String keyword,@RequestParam(defaultValue="1")int pageNum,@RequestParam(defaultValue="20")int pageSize,@RequestParam Map<String,String> filters){var result=chat.auditPage(scope(),userId,keyword,pageNum,pageSize,dateFilter(filters,"startTime","start_date"),dateFilter(filters,"endTime","end_date"));return PaismartTables.page((List<?>)result.get("rows"),Values.number(result.get("total"),0));}
    @GetMapping("/audit/conversations/{id}/messages") @PreAuthorize("@ss.hasPermi('paismart:conversation:audit')") @Log(title="知识会话正文审计",businessType=BusinessType.OTHER,isSaveRequestData=false,isSaveResponseData=false) public TableDataInfo auditMessages(@PathVariable String id,@RequestParam(defaultValue="1")int pageNum,@RequestParam(defaultValue="20")int pageSize){var result=chat.auditMessages(scope(),id,pageNum,pageSize);return PaismartTables.page((List<?>)result.get("rows"),Values.number(result.get("total"),0));}
    @GetMapping("/chat/generations/{id}") @PreAuthorize("@ss.hasPermi('paismart:chat:send')") public AjaxResult generation(@PathVariable String id){return success(chat.generation(PaismartIdentity.userId(),id));}
    @GetMapping({"/chat/active-generation","/chat/generations/active"}) @PreAuthorize("@ss.hasPermi('paismart:chat:send')") public AjaxResult active(){List<Map<String,Object>> rows=chat.active(PaismartIdentity.userId());return success(rows.isEmpty()?null:chat.generation(PaismartIdentity.userId(),Values.text(rows.get(0).get("generationId"))));}
    @PostMapping("/chat/generations/{id}/stop") @PreAuthorize("@ss.hasPermi('paismart:chat:send')") public AjaxResult stop(@PathVariable String id){chat.stop(PaismartIdentity.userId(),id);return success();}
    @GetMapping("/references/{id}") @PreAuthorize("@ss.hasPermi('paismart:document:read')") public AjaxResult reference(@PathVariable String id){return success(references.getReference(scope(),id));}
    @GetMapping("/conversations") @PreAuthorize("@ss.hasPermi('paismart:conversation:list')") public TableDataInfo conversations(@RequestParam(defaultValue="false")boolean archived,@RequestParam(required=false)String keyword,@RequestParam(defaultValue="1")int pageNum,@RequestParam(defaultValue="20")int pageSize,@RequestParam Map<String,String> filters){var result=chat.conversationPage(PaismartIdentity.userId(),archived,keyword,pageNum,pageSize,dateFilter(filters,"startTime","start_date"),dateFilter(filters,"endTime","end_date"));return PaismartTables.page((List<?>)result.get("rows"),Values.number(result.get("total"),0));}
    @PostMapping("/conversations") @PreAuthorize("@ss.hasPermi('paismart:chat:send')") public AjaxResult createConversation(@RequestBody Map<String,Object> body){return success(chat.createConversation(PaismartIdentity.userId(),Values.text(body.get("title")),Values.text(body.get("spaceId"))));}
    @GetMapping("/conversations/{id}/messages") @PreAuthorize("@ss.hasPermi('paismart:conversation:list')") public TableDataInfo messages(@PathVariable String id,@RequestParam(defaultValue="1")int pageNum,@RequestParam(defaultValue="20")int pageSize){var result=chat.messages(PaismartIdentity.userId(),id,pageNum,pageSize);return PaismartTables.page((List<?>)result.get("rows"),Values.number(result.get("total"),0));}
    @PutMapping("/conversations/{id}/{action}") @PreAuthorize("@ss.hasPermi('paismart:conversation:list')") @Log(title="知识会话",businessType=BusinessType.UPDATE)
    public AjaxResult conversationAction(@PathVariable String id,@PathVariable String action,@RequestBody Map<String,Object> body){if(!Set.of("archive","unarchive","switch").contains(action))throw new IllegalArgumentException("会话操作无效");if(!"switch".equals(action))chat.archive(PaismartIdentity.userId(),id,"archive".equals(action),Values.number(body.get("expectedVersion"),-1));return success(chat.selectConversation(PaismartIdentity.userId(),id));}
    @PostMapping("/chat/feedback") @PreAuthorize("@ss.hasPermi('paismart:chat:send')") public AjaxResult feedback(@RequestBody Map<String,Object> body){chat.feedback(PaismartIdentity.userId(),body);return success();}
    @GetMapping("/providers") @PreAuthorize("@ss.hasPermi('paismart:provider:list')") public TableDataInfo providers(){var rows=providers.listAll();return PaismartTables.page(rows,rows.size());}
    @GetMapping("/providers/{scope}") @PreAuthorize("@ss.hasPermi('paismart:provider:list')") public AjaxResult provider(@PathVariable String scope){return success(providers.scopeConfig(scope));}
    @PutMapping("/providers/{scope}") @PreAuthorize("@ss.hasPermi('paismart:provider:edit')") @Log(title="知识模型供应商",businessType=BusinessType.UPDATE,isSaveRequestData=false,isSaveResponseData=false) public AjaxResult saveProvider(@PathVariable String scope,@RequestBody Map<String,Object> body){return success(providers.save(scope,providers.adaptInput(scope,body)));}
    @PostMapping("/providers/{scope}/test") @PreAuthorize("@ss.hasPermi('paismart:provider:test')") @Log(title="知识供应商真实测试",businessType=BusinessType.OTHER,isSaveRequestData=false,isSaveResponseData=false) public AjaxResult test(@PathVariable String scope,@RequestHeader("Idempotency-Key")String key,@RequestBody(required=false)Map<String,Object> body){if(body!=null&&!Set.of("id").containsAll(body.keySet()))throw new IllegalArgumentException("供应商测试仅接受id");return success(providers.testForScope(PaismartIdentity.userId(),scope,body==null?"":Values.text(body.get("id")),key));}
    @GetMapping("/conflicts") @PreAuthorize("@ss.hasPermi('paismart:conflict:list')") public TableDataInfo conflicts(@RequestParam(required=false)String state,@RequestParam(defaultValue="1")int pageNum,@RequestParam(defaultValue="20")int pageSize){return page(governance.conflicts(scope(),state),pageNum,pageSize);}
    @PostMapping("/conflicts/{id}/resolve") @PreAuthorize("@ss.hasPermi('paismart:conflict:resolve')") @Log(title="知识冲突裁决",businessType=BusinessType.UPDATE) public AjaxResult resolve(@PathVariable String id,@RequestBody Map<String,Object> body){return success(governance.resolve(scope(),id,body));}
    @GetMapping("/indexes") @PreAuthorize("@ss.hasPermi('paismart:index:list')") public TableDataInfo indexes(){var rows=governance.indexes();return PaismartTables.page(rows,rows.size());}
    @PostMapping("/indexes/rebuild") @PreAuthorize("@ss.hasPermi('paismart:index:rebuild')") @Log(title="知识索引重建",businessType=BusinessType.OTHER) public AjaxResult rebuild(@RequestBody Map<String,Object> body,@RequestHeader("Idempotency-Key")String key){return success(job(governance.rebuild(PaismartIdentity.userId(),body,key)));}
    @PostMapping("/indexes/rollback") @PreAuthorize("@ss.hasPermi('paismart:index:rollback')") @Log(title="知识索引回滚",businessType=BusinessType.OTHER) public AjaxResult rollback(@RequestBody Map<String,Object> body,@RequestHeader("Idempotency-Key")String key){return success(job(governance.rollback(PaismartIdentity.userId(),body,key)));}
    @PostMapping("/indexes/recover") @PreAuthorize("@ss.hasPermi('paismart:index:rebuild')") @Log(title="知识索引恢复",businessType=BusinessType.OTHER) public AjaxResult recover(@RequestHeader("Idempotency-Key")String key){return success(job(governance.recoverIndex(PaismartIdentity.userId(),key)));}
    @GetMapping("/evaluations") @PreAuthorize("@ss.hasPermi('paismart:eval:list')") public TableDataInfo evaluations(@RequestParam(required=false)String keyword,@RequestParam(required=false)String state,@RequestParam(defaultValue="1")int pageNum,@RequestParam(defaultValue="20")int pageSize){var result=governance.evaluationPage(scope(),keyword,state,pageNum,pageSize);return PaismartTables.page((List<?>)result.get("rows"),Values.number(result.get("total"),0));}
    @GetMapping("/evaluation-datasets") @PreAuthorize("@ss.hasPermi('paismart:eval:list')") public TableDataInfo evaluationDatasets(@RequestParam(defaultValue="1")int pageNum,@RequestParam(defaultValue="20")int pageSize){var result=governance.datasetPage(scope(),pageNum,pageSize);return PaismartTables.page((List<?>)result.get("rows"),Values.number(result.get("total"),0));}
    @PostMapping(value="/evaluation-datasets",consumes="multipart/form-data") @PreAuthorize("@ss.hasPermi('paismart:eval:run')") @Log(title="知识评测样本上传",businessType=BusinessType.INSERT,isSaveRequestData=false,isSaveResponseData=false) public AjaxResult uploadEvaluationDataset(@RequestParam org.springframework.web.multipart.MultipartFile file,@RequestParam(required=false)String label,@RequestHeader("Idempotency-Key")String key){return success(governance.uploadDataset(scope(),file,label,key));}
    @PostMapping("/evaluations") @PreAuthorize("@ss.hasPermi('paismart:eval:run')") @Log(title="知识离线评测",businessType=BusinessType.OTHER,isSaveRequestData=false,isSaveResponseData=false) public AjaxResult evaluation(@RequestBody Map<String,Object> body,@RequestHeader("Idempotency-Key")String key){return success(job(governance.createEvaluation(PaismartIdentity.userId(),body,key)));}
    @GetMapping("/evaluations/{id}/report") @PreAuthorize("@ss.hasPermi('paismart:eval:list')") public AjaxResult report(@PathVariable String id){governance.requireEvaluation(scope(),id);return success(governance.report(id));}
    @GetMapping("/evaluations/{id}/reviews") @PreAuthorize("@ss.hasPermi('paismart:eval:review')") public TableDataInfo reviews(@PathVariable String id,@RequestParam(required=false)String caseId){governance.requireEvaluation(scope(),id);var rows=governance.reviews(id,caseId);return PaismartTables.page(rows,rows.size());}
    @PostMapping("/evaluations/{id}/reviews") @PreAuthorize("@ss.hasPermi('paismart:eval:review')") @Log(title="知识评测人工复核",businessType=BusinessType.UPDATE) public AjaxResult review(@PathVariable String id,@RequestBody Map<String,Object> body){governance.requireEvaluation(scope(),id);return success(governance.review(PaismartIdentity.userId(),id,body));}
}
